signature.advancedArgs:
{
  "type": "object",
  "properties": {
    "showTab": {
      "type": "string",
      "description": "Set when the user asks to see the dates on one tab of the Manual In and Out screen - e.g. 'what are the dates in the pending tab'. Pass the tab name as the user says it: Regularize, Pending, Valid Swipes or Off Shifts. No date is needed (the team and admin tools still need the employee). Returns only that tab's dates and submits nothing - show the dates as returned."
    },
    "date": {
      "type": "string",
      "description": "Date of the existing manual In and Out record to edit. Use the format returned by the dateFormat tool (MM/DD/YYYY for en-US, otherwise DD/MM/YYYY). Ask the user for this if not provided. Also call with the date when the user asks for the status of a pending request on that date - for a Pending day the tool returns the status, what was requested (old -> new In/Out and break times), the comment and who it is waiting for (pendingRequest); show that as returned."
    },
    "inDate": {
      "type": "string",
      "description": "In date, in the format returned by the dateFormat tool. Give it with inTime when the user is giving the In. The screen submits an In on its own, an Out on its own, or both, so one side is enough - ask the user which they want to give and never insist on the other. Offer suggested.inDate as the default; never assume it."
    },
    "inTime": {
      "type": "string",
      "description": "In time in HH:mm 24-hour format, e.g. 08:30. Give it with inDate when the user is giving the In; leave both out for an Out-only entry. Offer suggested.inTime as the default."
    },
    "outDate": {
      "type": "string",
      "description": "Out date, in the format returned by the dateFormat tool. Give it with outTime when the user is giving the Out; leave both out for an In-only entry. An Out Date on the day AFTER the In Date is normal for shifts past midnight (shiftDetails.canEndNextDay) - never question it. Offer suggested.outDate as the default."
    },
    "outTime": {
      "type": "string",
      "description": "Out time in HH:mm 24-hour format, e.g. 17:30. Give it with outDate when the user is giving the Out. Check it against outDate, not against inTime. Offer suggested.outTime as the default."
    },
    "clearInTime": {
      "type": "boolean",
      "description": "Set to true when the user wants to remove (clear) the recorded In time, as the Valid Swipes grid allows - e.g. 'delete my in time for 05/11/2024'. Do not also give inTime. Needs a reason; the day is submitted with the In empty."
    },
    "clearOutTime": {
      "type": "boolean",
      "description": "Set to true when the user wants to remove (clear) the recorded Out time. Do not also give outTime. Can be combined with clearInTime to clear both. Needs a reason."
    },
    "deleteBreaks": {
      "type": "array",
      "items": {
        "type": "integer"
      },
      "description": "Numbers (breakNo, from shiftDetails.recordedBreaks) of the recorded breaks the user wants to delete - e.g. [1]. Deleting breaks alone is a valid edit; it needs a reason. Do not also change the same break in breaks."
    },
    "reason": {
      "type": "string",
      "description": "Reason/comment explaining why the manual In and Out is being changed. Required before the update is submitted."
    },
    "otherEntries": {
      "type": "array",
      "description": "When the user asks for several days in one request, pass on every call the OTHER days of that request that are not submitted yet, each with the values the user gave. The screen submits such days together and refuses all of them when two overlap across midnight, so the tool checks the overlap in each day's preview. Preview every day first; submit none until all previews passed.",
      "items": {
        "type": "object",
        "properties": {
          "date": {
            "type": "string",
            "description": "That day, in the dateFormat format."
          },
          "inDate": {
            "type": "string"
          },
          "inTime": {
            "type": "string",
            "description": "HH:mm"
          },
          "outDate": {
            "type": "string"
          },
          "outTime": {
            "type": "string",
            "description": "HH:mm"
          }
        }
      }
    },
    "confirmed": {
      "type": "boolean",
      "description": "Set to true, together with previewToken, only after the user has reviewed the preview of current vs new values and explicitly confirmed. Set to false (or omit) to just preview/validate without updating anything. Never send it on the first call - the tool validates and returns the preview first."
    },
    "previewToken": {
      "type": "string",
      "description": "The previewToken from the preview the user confirmed. Required with confirmed:true. Without it, or if any value changed since that preview, nothing is submitted and the preview is returned again - show it and ask for confirmation."
    },
    "breaks": {
      "type": "array",
      "description": "Optional breaks - none, one or as many as the user wants. After showing the shift details, tell the user they can add breaks or change a recorded one, but do not insist. Each break needs both times, must end after it starts, must sit within the In and Out date-times and the shift's allowed period, and must not overlap another break of the day (shiftDetails.recordedBreaks lists the ones already recorded). A break after midnight is fine on a shift whose period reaches there.",
      "items": {
        "type": "object",
        "properties": {
          "breakInTime": {
            "type": "string",
            "description": "Break start time in HH:mm 24-hour format, e.g. 12:00."
          },
          "breakOutTime": {
            "type": "string",
            "description": "Break end time in HH:mm 24-hour format, e.g. 13:00."
          },
          "breakNo": {
            "type": "integer",
            "description": "Only to CHANGE a recorded break: its breakNo from shiftDetails.recordedBreaks. Leave it out to add a new break."
          }
        },
        "required": [
          "breakInTime",
          "breakOutTime"
        ]
      }
    },
    "breakInTime": {
      "type": "string",
      "description": "Single-break shorthand: break start time in HH:mm (adds a new break). Prefer the breaks list. If given, breakOutTime must be given too."
    },
    "breakOutTime": {
      "type": "string",
      "description": "Single-break shorthand: break end time in HH:mm (adds a new break). Prefer the breaks list. If given, breakInTime must be given too."
    },
    "dateSelectMode": {
      "enum": [
        "last7days",
        "last30days",
        "period"
      ],
      "description": "Search Criteria date selection mode, matching the page radio buttons: last7days (Last 7 Days), last30days (Last 30 Days), period (By Period, uses fromDate/toDate). Defaults to period with a wide range."
    },
    "fromDate": {
      "type": "string",
      "description": "Search range start date in the format returned by the dateFormat tool. Only used when dateSelectMode is period. If omitted, a wide default range is used. The date being edited must fall inside the range."
    },
    "toDate": {
      "type": "string",
      "description": "Search range end date in the format returned by the dateFormat tool. Only used when dateSelectMode is period. If omitted, a wide default range is used. The date being edited must fall inside the range."
    },
    "isGroupByEmployee": {
      "type": "boolean",
      "description": "Optional Group By Employee checkbox on the Search Criteria panel. Omit it to use the screen's own default."
    },
    "rosterGroup": {
      "type": "string",
      "description": "Optional roster group, by id or name, as listed by submitSelfManualInAndOut with showRosters. Omit it to use the screen's first roster group. Do not ask the user for it unless they want a specific roster."
    },
    "rosterCode": {
      "type": "string",
      "description": "Optional roster code. Takes precedence over rosterName. Omit it to use the first roster of the roster group, as the screen does."
    },
    "rosterName": {
      "type": "string",
      "description": "Optional roster name. Resolved to a roster code within the roster group. Ignored when rosterCode is given."
    }
  },
  "required": [
    "date"
  ]
}
